from pwn import remote

r = remote('crypto.chal.csaw.io', 5000)
# Print all output for more than 30 seconds or until after Enter N
output = b''
while b'Enter N: ' not in output:
    try:
        output += r.recv(timeout=3)
    except Exception as e:
        break
print(output.decode(errors='ignore'))
# Now try to get N as next line, just in case
def safe_recvline():
    try:
        return r.recvline(timeout=2)
    except Exception:
        return b''

n_line = safe_recvline()
print('N:', n_line.decode(errors='ignore'))
with open('/home/ctfplayer/ctf_files/chal_n.txt','w') as f:
    f.write(n_line.decode(errors='ignore').strip())
